17	import type { Organization } from "@/types/organization";
18	import type { Project } from "@/types/project";
19	import type { ReactElement } from "react";
20	import { organizationResource } from "../permission/resources";
21	import { OrgSwitcher } from "./org-switcher";
22	
23	export type AppSidebarProps = {
24	  org: Organization;
25	  actor: Actor;
26	  flags: FeatureFlagSnapshot;
27	  projects: readonly Project[];
28	  pathname: string;
29	  /** Orgs offered by the switcher; defaults to just the current one. */
30	  organizations?: readonly Organization[];
31	};
32	
33	/** True when `pathname` is the item's route or lives beneath it. */
34	export function isActiveSegment(pathname: string, href: string): boolean {
35	  return pathname === href || pathname.startsWith(`${href}/`);
36	}
37	
38	export function AppSidebar(props: AppSidebarProps): ReactElement | null {
39	  const { org, actor, flags, projects, pathname, organizations } = props;
40	
41	  // The nav tree declares the permission and flag each item needs; `visibleNav`
42	  // applies both. Nothing here branches on `actor.role`.
43	  const context = orgFlagContext(org, actor);
44	  const primary = visibleNav(SIDEBAR_NAV, actor, flags);
45	  const settings = visibleNav(SETTINGS_NAV, actor, flags);
46	
47	  // The project shortcut list is its own gate: reading projects at all, and
48	  // the public-projects flag for the "shared" affordance.
49	  const mayReadProjects = can(
50	    actor,
51	    "project:read",
52	    organizationResource(org.id),
53	  );
54	  const publicProjectsOn =
55	    flags.public_projects === true || isEnabled("public_projects", context);
56	
57	  function renderItem(item: NavItem): ReactElement {
58	    const href = orgPath(org.slug, item.segment);
59	    return (
60	      <li key={item.key}>
61	        <Link
62	          href={href}
63	          className={cn(
64	            "block rounded px-2 py-1 text-sm",
65	            isActiveSegment(pathname, href)
66	              ? "bg-neutral-200 font-medium"
67	              : "hover:bg-neutral-100",
68	          )}
69	        >
