 * `status=open` / `status=closed` in the filter vocabulary (ADR 0009 #3):
 * groups that expand to their member statuses wherever a status filter is
 * read, so a page and an API caller agree on what the group means.
 */
export type IssueStatusGroup = "open" | "closed";

export const STATUS_GROUPS: Readonly<Record<IssueStatusGroup, readonly IssueStatus[]>> = {
  open: ISSUE_STATUSES.filter((status) => !CLOSED_ISSUE_STATUSES.includes(status)),
  closed: CLOSED_ISSUE_STATUSES,
};

export type IssueStatusFilterValue = IssueStatus | IssueStatusGroup;

function isStatusGroup(value: IssueStatusFilterValue): value is IssueStatusGroup {
  return value === "open" || value === "closed";
}

/** Expands any status groups in `values` to their members, deduplicated and
 *  returned in `ISSUE_STATUSES` order so callers get a stable result. */
export function expandStatusFilter(
  values: readonly IssueStatusFilterValue[],
): readonly IssueStatus[] {
  const expanded = new Set<IssueStatus>();
  for (const value of values) {
    if (isStatusGroup(value)) {
      for (const status of STATUS_GROUPS[value]) expanded.add(status);
    } else {
      expanded.add(value);
    }
  }
  return ISSUE_STATUSES.filter((status) => expanded.has(status));
}

