/** A bare `YYYY-MM-DD`, as opposed to a full ISO-8601 instant. */
export const CALENDAR_DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

export function isCalendarDate(value: string): boolean {
  return CALENDAR_DATE_PATTERN.test(value);
}

/**
 * The exclusive upper bound a `due_before` filter compares against (ADR 0009
 * #5). A calendar date matches issues due any time on that UTC day or
 * earlier, so the bound is the instant the next day begins; a full timestamp
 * is already the bound, unchanged.
 */
export function dueBeforeBound(value: IsoTimestamp): IsoTimestamp {
  if (!isCalendarDate(value)) return value;
  return toIsoTimestamp(new Date(parseIso(value).getTime() + DAY_MS));
}

