/**
 * Adapts a Next.js `searchParams` record to `ReadableParams`, so a server
 * page reads the filter through `parseIssueFilterParams` instead of parsing
 * the query string itself — the two would otherwise drift, as ADR 0009 notes.
 */
export function readableSearchParams(
  search: Record<string, string | string[] | undefined>,
): ReadableParams {
  return {
    get(name: string): string | null {
      const value = search[name];
      if (value === undefined) return null;
      return Array.isArray(value) ? (value[0] ?? null) : value;
    },
  };
}

