/**
 * Project issue list; parses filters from `await searchParams`.
 *
 * Owner D. The filter is rebuilt from the URL on every render rather than kept
 * in component state, so a filtered list is a shareable link. Parsing goes
 * through the shared codec and schema (ADR 0009 #1) rather than picking a few
 * query parameters by hand, so every filter dimension — not just status and
 * search — actually narrows the list.
 *
 * Must call (do not reimplement): can
 */

import Link from "next/link";
import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { PENDING_ISSUE_ID } from "@/actions/_lib/permission-resources";
import { IssueList } from "@/components/domain/issue/issue-list";
import { EmptyState } from "@/components/ui/empty-state";
import {
  issueFilterQueryString,
  parseIssueFilterParams,
  readableSearchParams,
} from "@/hooks/issue-filter-params";
import { can } from "@/lib/permissions";
import { issueFilterSchema } from "@/schemas/issue";
import { searchParamsPaginationSchema } from "@/schemas/pagination";
import { getIssue, listIssues } from "@/server/services/issue-service";
import type { IssueFilter, IssueWithRelations } from "@/types/issue";
import { loadProjectContext } from "../../../_lib/project-context";

type PageParams = { orgSlug: string; projectSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Issues",
};

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug, projectSlug } = await props.params;
  const search = await props.searchParams;

  const { org, actor, project } = await loadProjectContext(orgSlug, projectSlug);

  const mayRead = can(actor, "issue:read", {
    kind: "issue",
    orgId: org.id,
    projectId: project.id,
    issueId: PENDING_ISSUE_ID,
    authorId: actor.userId,
    assigneeId: actor.userId,
  });
  if (!mayRead) {
    notFound();
  }

  const mayCreate = can(actor, "issue:create", {
    kind: "issue",
    orgId: org.id,
    projectId: project.id,
    issueId: PENDING_ISSUE_ID,
    authorId: actor.userId,
    assigneeId: null,
  });

  const pagination = searchParamsPaginationSchema.parse(search);
  const urlFilter = parseIssueFilterParams(readableSearchParams(search));

  // The filter goes through the shared schema so an unparseable URL is a
  // rejected filter rather than a malformed repository query.
  const filter = issueFilterSchema.parse({
    ...urlFilter,
    orgId: org.id,
    projectId: project.id,
    limit: pagination.perPage,
    cursor: pagination.cursor ?? null,
  });

  const page = await listIssues(actor, filter);
  const rows: IssueWithRelations[] = await Promise.all(
    page.items.map((issue) => getIssue(actor, org.id, issue.id)),
  );

  const basePath = `/${orgSlug}/projects/${projectSlug}/issues`;
  const archivedLabel = urlFilter.archivedOnly
    ? "Archived only"
    : urlFilter.includeArchived
      ? "Archived included"
      : null;

  return (
    <div className="space-y-6">
      <div className="flex items-baseline justify-between">
        <p className="text-sm text-slate-600">
          {page.total} issues in {project.name}
          {archivedLabel ? `, ${archivedLabel.toLowerCase()}` : ""}
        </p>
        <div className="flex items-center gap-4 text-sm">
          <Link href={`${basePath}${nextArchivedQueryString(urlFilter)}`} className="text-slate-600">
            {nextArchivedLabel(urlFilter)}
          </Link>
          {mayCreate ? (
            <Link
              href={`${basePath}/new`}
              className="rounded-md bg-indigo-600 px-3 py-1.5 text-sm font-medium text-white"
            >
              New issue
            </Link>
          ) : null}
        </div>
      </div>

      {rows.length === 0 ? (
        <EmptyState
          title="No issues match this filter"
          description="Clear the filter, or file the first issue in this project."
        />
      ) : (
        <IssueList issues={rows} actor={actor} />
      )}
    </div>
  );
}

/**
 * The archived toggle cycles live → included → only → live, each step a link
 * built from the shared codec so every other filter dimension survives the
 * click (ADR 0009 #6: archived-only is a real view, not a side effect of
 * "show archived").
 */
function nextArchivedFilter(filter: IssueFilter): IssueFilter {
  const { includeArchived: _includeArchived, archivedOnly: _archivedOnly, ...rest } = filter;
  if (filter.archivedOnly === true) return rest;
  if (filter.includeArchived === true) return { ...rest, archivedOnly: true };
  return { ...rest, includeArchived: true };
}

function nextArchivedLabel(filter: IssueFilter): string {
  if (filter.archivedOnly === true) return "Show live issues";
  if (filter.includeArchived === true) return "Show archived only";
  return "Show archived";
}

function nextArchivedQueryString(filter: IssueFilter): string {
  return issueFilterQueryString(nextArchivedFilter(filter));
}

