/** Adds or removes one status without disturbing the other dimensions. */
export function toggleStatus(
  filter: IssueFilter,
  status: IssueStatus,
): IssueFilter {
  const current = filter.status ?? [];
  const next = current.includes(status)
    ? current.filter((value) => value !== status)
    : [...current, status];
  const { status: _dropped, ...rest } = filter;
  return next.length === 0 ? rest : { ...rest, status: next };
}

/**
 * Sets (or clears) the whole status dimension to one group's members in a
 * single click — the shortcut for "open" / "closed" the status chips lacked
 * on their own (ADR 0009 #3): without it, matching `status=open` took four
 * individual chip clicks.
 */
export function toggleStatusGroup(
  filter: IssueFilter,
  group: IssueStatusGroup,
): IssueFilter {
  const { status: _dropped, ...rest } = filter;
  return isStatusGroupActive(filter, group) ? rest : { ...rest, status: [...STATUS_GROUPS[group]] };
}

function isStatusGroupActive(filter: IssueFilter, group: IssueStatusGroup): boolean {
  const current = filter.status ?? [];
  const members = STATUS_GROUPS[group];
  return current.length === members.length && members.every((status) => current.includes(status));
}

const STATUS_GROUP_LABELS: Readonly<Record<IssueStatusGroup, string>> = {
  open: "Open",
  closed: "Closed",
};

