import { issueFilterSchema } from "@/schemas/issue";
import { parseIssueFilterParams, issueFilterToParams } from "@/hooks/issue-filter-params";
import { dueBeforeBound } from "@/lib/date";

function assertEq(actual: unknown, expected: unknown, label: string) {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) {
    console.error(`FAIL ${label}: got ${a}, want ${e}`);
    process.exitCode = 1;
  } else {
    console.log(`ok   ${label}`);
  }
}

// 1. assignee=me parses and schema accepts it
{
  const filter = parseIssueFilterParams(new URLSearchParams("assignee=me"));
  assertEq(filter.assigneeId, "me", "codec parses assignee=me");
  const parsed = issueFilterSchema.parse({ orgId: "01HZZZPPPPPPPPPPPPPPPPPPPP", assigneeId: "me" });
  assertEq(parsed.assigneeId, "me", "schema accepts assigneeId=me");
}

// 2. assignee=none -> null, distinct from undefined
{
  const filter = parseIssueFilterParams(new URLSearchParams("assignee=none"));
  assertEq(filter.assigneeId, null, "codec parses assignee=none as null");
}

// 3. status=open expands to the open statuses
{
  const filter = parseIssueFilterParams(new URLSearchParams("status=open"));
  assertEq(filter.status, ["backlog", "todo", "in_progress", "in_review"], "status=open expands");
}

// 4. status=closed expands
{
  const filter = parseIssueFilterParams(new URLSearchParams("status=closed"));
  assertEq(filter.status, ["done", "canceled"], "status=closed expands");
}

// 5. schema accepts group tokens directly (API caller bypassing the codec)
{
  const parsed = issueFilterSchema.parse({ orgId: "01HZZZPPPPPPPPPPPPPPPPPPPP", status: ["open"] });
  assertEq(parsed.status, ["open"], "schema accepts status group literally (expansion happens in repo)");
