import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);

import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";

let cleanup: () => void;
let tenant: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("verify-tmp");
});

afterAll(() => {
  cleanup();
});

describe("tmp verify", () => {
  it("label filter is all-of, not any-of", async () => {
    const bug = await labelRepo.insertLabel({ orgId: tenant.org.id, name: "bug", color: "#ef4444", description: null });
    const regression = await labelRepo.insertLabel({ orgId: tenant.org.id, name: "regression", color: "#f97316", description: null });

    const n1 = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const both = await issueRepo.insertIssue(
      { ...issueInput(tenant.org.id, tenant.project.id, { title: "Has both" }), labelIds: [bug.id, regression.id] },
      tenant.userIds.owner,
      n1,
    );

    const n2 = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    await issueRepo.insertIssue(
      { ...issueInput(tenant.org.id, tenant.project.id, { title: "Has only bug" }), labelIds: [bug.id] },
      tenant.userIds.owner,
      n2,
    );

    const page = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
      labelIds: [bug.id, regression.id],
    });

    expect(page.items.map((i) => i.id)).toEqual([both.id]);
    expect(page.total).toBe(1);
  });

  it("unassigned (null) narrows the list; undefined does not", async () => {
    const n1 = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const unassigned = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, { title: "Nobody has this", assigneeId: null }),
      tenant.userIds.owner,
      n1,
    );
    const n2 = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, { title: "Someone has this", assigneeId: tenant.userIds.member }),
      tenant.userIds.owner,
      n2,
    );

    const unassignedPage = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
      assigneeId: null,
    });
    expect(unassignedPage.items.map((i) => i.id)).toContain(unassigned.id);
    expect(unassignedPage.items.every((i) => i.assigneeId === null)).toBe(true);

    const anyonePage = await issueRepo.listIssues({ orgId: tenant.org.id, limit: 100, cursor: null });
    expect(anyonePage.total).toBeGreaterThanOrEqual(2);
  });

  it("archivedOnly lists archived issues and nothing else", async () => {
    const n1 = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const toArchive = await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, { title: "Will be archived" }),
      tenant.userIds.owner,
      n1,
    );
    await issueRepo.archiveIssue(tenant.org.id, toArchive.id);

    const page = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
      archivedOnly: true,
    });

    expect(page.items.every((i) => i.archivedAt !== null)).toBe(true);
    expect(page.items.map((i) => i.id)).toContain(toArchive.id);
  });

  it("due_before as a calendar date includes the whole day", async () => {
    const n1 = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const dueOnDay = await issueRepo.insertIssue(
      { ...issueInput(tenant.org.id, tenant.project.id, { title: "Due during the day" }), dueAt: "2026-03-15T18:00:00.000Z" as any },
      tenant.userIds.owner,
      n1,
    );

    const page = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
      dueBefore: "2026-03-15" as any,
    });

    expect(page.items.map((i) => i.id)).toContain(dueOnDay.id);
  });

  it("status group 'open' expands in the repository", async () => {
    const n1 = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    const inProgress = await issueRepo.insertIssue(
      { ...issueInput(tenant.org.id, tenant.project.id, { title: "In progress for group test" }), status: "in_progress" as any },
      tenant.userIds.owner,
      n1,
    );
    const n2 = await issueRepo.nextIssueNumber(tenant.org.id, tenant.project.id);
    await issueRepo.insertIssue(
      { ...issueInput(tenant.org.id, tenant.project.id, { title: "Done for group test" }), status: "done" as any },
      tenant.userIds.owner,
      n2,
    );

    const page = await issueRepo.listIssues({
      orgId: tenant.org.id,
      limit: 100,
      cursor: null,
      status: ["open"] as any,
    });

    expect(page.items.map((i) => i.id)).toContain(inProgress.id);
    expect(page.items.every((i) => i.status !== "done")).toBe(true);
  });
});

